\pset tuples_only on
\pset format unaligned
SELECT jsonb_build_object('section','clock','at',clock_timestamp(),'timezone',current_setting('TimeZone'),'connection_ro',current_setting('default_transaction_read_only'),'transaction_ro',current_setting('transaction_read_only'));
SELECT jsonb_build_object('section','http_operation_audit_count','count',count(*)) FROM sys_operation_logs WHERE request_path LIKE '%/packaging/terminal/warehouse/confirm%';
SELECT jsonb_build_object('section','generic_audit_at_failure','id',log_id,'at',created_at,'user_id',user_id,'user_name',user_name,'action',action,'type',entity_type,'entity_id',entity_id,'after',after_value) FROM sys_audit_log WHERE created_at >= '2026-09-10 09:09:55' AND created_at < '2026-09-10 09:10:10' ORDER BY log_id LIMIT 12;
SELECT jsonb_build_object('section','house_ownership','house',h.house_code,'farm',h.farm_code,'house_status',h.status,'farm_status',f.status,'company',f.company_code) FROM brd_houses h LEFT JOIN brd_farms f ON f.farm_code=h.farm_code WHERE h.house_code IN (SELECT house_code FROM pkg_source_batches WHERE id IN (46,47,49,50));
SELECT jsonb_build_object('section','grade_dictionary','code',dict_code,'status',status,'config',config_json) FROM sys_dict WHERE dict_type IN ('PKG_EGG_GRADE','PKG_EGG_DEFECT') ORDER BY dict_code;
SELECT jsonb_build_object('section','candidate_products','table',table_name,'columns',jsonb_agg(column_name ORDER BY ordinal_position)) FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('products','product_master','product_products') GROUP BY table_name;
SELECT jsonb_build_object('section','wms_direct_reference','packing_id',p.id,'count',count(w.id),'rows',COALESCE(jsonb_agg(jsonb_build_object('id',w.id,'task_no',w.task_no,'inbound_no',w.inbound_no,'status',w.status,'qty',w.qty)) FILTER (WHERE w.id IS NOT NULL),'[]')) FROM pkg_packing_records p LEFT JOIN wms_inbound w ON w.task_no=p.code OR w.inbound_no=p.code OR w.source_order_no=p.code WHERE p.id IN (33,34) GROUP BY p.id;
SELECT jsonb_build_object('section','wms_observed_window','count',count(*)) FROM wms_inbound WHERE created_at >= '2026-09-10 09:09:55' AND created_at < '2026-09-10 09:11:40';
SELECT jsonb_build_object('section','existing_handover_idempotency','packing_id',p.id,'packing_code',p.code,'status',p.status,'is_test',p.is_test,'expected_qty',p.total_eggs,'handover_count',(SELECT count(*) FROM pkg_handover_records h WHERE h.packing_code=p.code),'batch_count',(SELECT count(*) FROM inv_batches b WHERE b.packaging_batch_ref=p.code),'batch_qty',(SELECT COALESCE(sum(qty),0) FROM inv_batches b WHERE b.packaging_batch_ref=p.code),'ledger_qty',(SELECT COALESCE(sum(qty_change),0) FROM inv_ledger WHERE ref_no=p.code AND change_type='PACKAGING_INBOUND')) FROM pkg_packing_records p WHERE id IN (30,33,34);
SELECT jsonb_build_object('section','handover_unique_constraints','name',conname,'definition',pg_get_constraintdef(oid)) FROM pg_constraint WHERE conrelid='pkg_handover_records'::regclass AND contype IN ('u','p');
SELECT jsonb_build_object('section','inventory_totals','batches',(SELECT count(*) FROM inv_batches),'ledger',(SELECT count(*) FROM inv_ledger));
-- Both identities exist in repository history; report actual rows without inventing a product code.
SELECT jsonb_build_object('section','runtime_product','row',to_jsonb(p)) FROM mst_products p WHERE product_code IN ('PRD-EGG-GRADE_5','PRD-EGG-5','PRD-EGG-GRADE_1');
SELECT jsonb_build_object('section','legacy_product_table','row',to_jsonb(p)) FROM product_master p WHERE product_code IN ('PRD-EGG-GRADE_5','PRD-EGG-5','PRD-EGG-GRADE_1');
SELECT jsonb_build_object('section','gift_sku_coverage','grade',g.grade_code,'runtime_product','PRD-EGG-'||g.grade_code,'active_exact_count',(SELECT count(*) FROM product_skus s WHERE s.product_code='PRD-EGG-'||g.grade_code AND s.grade_code=g.grade_code AND s.spec_code='PKG_PACK_SPEC_3' AND s.status='ACTIVE'),'all_product_candidates',(SELECT COALESCE(jsonb_agg(jsonb_build_object('code',sku_code,'product',product_code,'status',status)),'[]') FROM product_skus s WHERE s.grade_code=g.grade_code AND s.spec_code='PKG_PACK_SPEC_3')) FROM product_grades g WHERE g.status='ACTIVE' AND g.is_saleable ORDER BY g.grade_code;
